	private static Group group(Shape shape) {
		StatementPattern category = new StatementPattern(Var.of("e"), Var.of("p", P, true, true), Var.of("x"));
		StatementPattern type = new StatementPattern(Var.of("e"), Var.of("q", Q, true, true),
				Var.of("tag", TAG, true, true));
		TupleExpr relation;
		if (shape == Shape.TWO_PATTERNS) {
			relation = new Join(category, type);
		} else if (shape == Shape.LOCAL_FILTER) {
			relation = new Filter(new Join(new Join(category, type), values()),
					new Compare(Var.of("x"), Var.of("t")));
		} else {
			Filter condition = new Filter(values(), new Compare(Var.of("x"), Var.of("t")));
			condition.setConditionBindingScope(ConditionBindingScope.retain(Set.of("x", "t")));
			relation = new Join(category, new Join(type, condition));
		}
		Group group = new Group(relation);
		group.addGroupElement(new GroupElem("count", new Count(Var.of("e"), true)));
		return group;
	}

	private static BindingSetAssignment values() {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setDeclaredBindingNames(Set.of("t"));
		assignment.setBindingSets(List.of(binding("t", A), binding("t", B)));
		return assignment;
	}

	private static MapBindingSet binding(String name, Value value) {
		MapBindingSet result = new MapBindingSet();
		result.addBinding(name, value);
		return result;
	}

	private static Map<String, Value> expected(Shape shape, Input input) {
		int count = shape == Shape.TWO_PATTERNS || input.variable() == null || input.variable().equals("g") ? 2
				: input.value().equals(A) ? 1 : 0;
		Map<String, Value> result = new HashMap<>();
		result.put("count", VF.createLiteral(Integer.toString(count), XSD.INTEGER));
		if (input.variable() != null) {
			result.put(input.variable(), input.value());
		}
		return Map.copyOf(result);
	}

	private static void enableTelemetry(TupleExpr root, Group group) {
		root.setRuntimeTelemetryEnabled(true);
		root.setExecutionSummaryEnabled(true);
		group.setRuntimeTelemetryEnabled(true);
		group.setExecutionSummaryEnabled(true);
	}

	private static Observation evaluate(QueryEvaluationStep step, TupleExpr root, Group group, BindingSet input) {
		root.setStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH, null);
		root.setStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN, null);
		group.setStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH, null);
		group.setStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN, null);
		long rootBefore = count(root);
		long groupBefore = root == group ? 0 : count(group);
		List<Map<String, Value>> rows = new ArrayList<>();
		List<Boolean> suppliedGraph = new ArrayList<>();
		try (var iteration = step.evaluate(input)) {
			while (iteration.hasNext()) {
				Map<String, Value> row = new HashMap<>();
				BindingSet actual = iteration.next();
				suppliedGraph.add(GraphFrameBindings.isSupplied(actual, "g"));
				actual.forEach(binding -> row.put(binding.getName(), binding.getValue()));
				rows.add(Map.copyOf(row));
			}
		}
		return new Observation(List.copyOf(rows), List.copyOf(suppliedGraph), count(root) - rootBefore,
				root == group ? 0 : count(group) - groupBefore,
				root.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH),
				group.getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH),
				root.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN),
				group.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN), step.getClass().getName());
	}

	private static long count(QueryModelNode node) {
		return Math.max(0L, node.getLongMetricActual("nativeInvocationsActual"));
	}
